sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {


        var tradeMarket = g_scratchpad.ownB;
        var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
        eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
        eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
        eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
        eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
        eligbleCheck.getXMLAnswer(handleEligiblity);

        function handleEligiblity(check) { //Evaluate if the Outcome is amend Trade
            if (check.toString() == 'true') {
                g_form.setLabelOf('settlement_date', 'Settlement Date'); //fix for 7405
                var getFieldstoHide = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
                getFieldstoHide.addParam('sysparm_name', 'hideAmendFieldsBasedonMarket');
                getFieldstoHide.addParam('sysparm_tradeMarket', tradeMarket);
                getFieldstoHide.getXMLAnswer(getFields);

                function getFields(responseFields) { //get all the fields to hide
                    var jsonValues = responseFields.split(',');
                    for (var i = 0; i < jsonValues.length; i++) {
                        var taskField = jsonValues[i]
                        g_form.setMandatory(taskField, false); //setting amndatory and display false
                        g_form.setDisplay(taskField, false);

                    }
					// MSSCUSTODY-8065
                    if (g_scratchpad.hasAfterConfTradeStatus && tradeMarket == 'DCC JP') {
                        g_form.setReadOnly('settlement_date', true);
                    }
                }

            }
        }


        return;
    }

    var tradeMarket = g_scratchpad.ownB;
    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(handleEligiblity);

    function handleEligiblity(check) { //Evaluate if the Outcome is amend Trade
        if (check.toString() == 'true') {
            g_form.setLabelOf('settlement_date', 'Settlement Date'); //fix for 7405
            var getFieldstoHide = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
            getFieldstoHide.addParam('sysparm_name', 'hideAmendFieldsBasedonMarket');
            getFieldstoHide.addParam('sysparm_tradeMarket', tradeMarket);
            getFieldstoHide.getXMLAnswer(getFields);

            function getFields(responseFields) { //get all the fields to hide
                var jsonValues = responseFields.split(',');
                for (var i = 0; i < jsonValues.length; i++) {
                    var taskField = jsonValues[i]
                    g_form.setMandatory(taskField, false); //setting amndatory and display false
                    g_form.setDisplay(taskField, false);

                }
				// MSSCUSTODY-8065
				if (g_scratchpad.hasAfterConfTradeStatus && tradeMarket == 'DCC JP') {
                        g_form.setReadOnly('settlement_date', true);
                    }
            }

        }
    }

}
